with latest as (
  select distinct on (lower(trim(company)))
    company, person, email, address, phone, memo
  from tmp_client_import
  where trim(company) <> ''
  order by lower(trim(company)), seq
)
update public.client c
set
  contact_name = coalesce(nullif(l.person,''), c.contact_name),
  phone        = coalesce(nullif(l.phone,''), c.phone),
  email        = coalesce(nullif(l.email,''), c.email),
  address      = coalesce(nullif(l.address,''), c.address),
  memo         = case
                   when nullif(l.memo,'') is null then c.memo
                   when nullif(c.memo,'') is null then l.memo
                   when position(l.memo in c.memo) > 0 then c.memo
                   else c.memo || E'\n[2025~2026 명함 업데이트] ' || l.memo
                 end
from latest l
where c.deleted_at is null
  and lower(trim(c.name)) = lower(trim(l.company));

with latest as (
  select distinct on (lower(trim(company)))
    company, person, email, address, phone, memo
  from tmp_client_import
  where trim(company) <> ''
  order by lower(trim(company)), seq
)
insert into public.client(name,contact_name,phone,email,address,memo)
select
  l.company,
  nullif(l.person,''),
  nullif(l.phone,''),
  nullif(l.email,''),
  nullif(l.address,''),
  nullif(l.memo,'')
from latest l
where not exists (
  select 1
  from public.client c
  where c.deleted_at is null
    and lower(trim(c.name)) = lower(trim(l.company))
);

with client_map as (
  select distinct on (lower(trim(name)))
    id, name
  from public.client
  where deleted_at is null
  order by lower(trim(name)), created_at desc
),
src as (
  select
    t.*,
    cm.id as client_id,
    row_number() over(partition by lower(trim(t.company)) order by t.seq) as rn
  from tmp_client_import t
  join client_map cm on lower(trim(cm.name)) = lower(trim(t.company))
  where nullif(trim(t.person),'') is not null
)
insert into public.client_contact(client_id,name,position,phone,email,is_primary,memo)
select
  s.client_id,
  s.person,
  nullif(s.position,''),
  nullif(s.phone,''),
  nullif(s.email,''),
  case
    when s.rn = 1
      and not exists (
        select 1 from public.client_contact x
        where x.client_id=s.client_id
          and x.deleted_at is null
          and x.is_primary=true
      )
    then true else false
  end,
  nullif(s.memo,'')
from src s
where not exists (
  select 1
  from public.client_contact x
  where x.client_id=s.client_id
    and x.deleted_at is null
    and lower(trim(x.name))=lower(trim(s.person))
    and (
      (nullif(s.phone,'') is not null and regexp_replace(coalesce(x.phone,''),'\D','','g') = regexp_replace(s.phone,'\D','','g'))
      or
      (nullif(s.email,'') is not null and lower(trim(coalesce(x.email,''))) = lower(trim(s.email)))
      or
      (nullif(s.phone,'') is null and nullif(s.email,'') is null)
    )
);

select
  (select count(*) from tmp_client_import) as source_contacts,
  (select count(distinct lower(trim(company))) from tmp_client_import) as source_companies,
  (select count(*) from public.client c
     where c.deleted_at is null
       and exists(select 1 from tmp_client_import t where lower(trim(t.company))=lower(trim(c.name)))) as matched_clients,
  (select count(*) from public.client_contact cc
     where cc.deleted_at is null
       and exists(
         select 1 from tmp_client_import t
         join public.client c on c.id=cc.client_id
         where c.deleted_at is null
           and lower(trim(t.company))=lower(trim(c.name))
           and lower(trim(t.person))=lower(trim(cc.name))
       )) as matched_contacts;

commit;
